import importlib.abc, importlib.util, os, sys
from urllib.parse import urlsplit, unquote
from pathlib import Path
MAIN = Path('/Users/turshevr/toto-ai')
TEMP = Path(__file__).resolve().parent.parent
blocked = []
allowed_python_subprocesses = []
class MainOnly(importlib.abc.MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        if fullname == 'toto_ai':
            return importlib.util.spec_from_file_location(fullname, MAIN / 'src/toto_ai/__init__.py', submodule_search_locations=[str(MAIN / 'src/toto_ai')])
def audit(event, args):
    if event.startswith(('socket.connect','socket.getaddrinfo','socket.gethostby','socket.sendto','os.system','os.posix_spawn','os.exec')):
        blocked.append({'event':event,'test':os.environ.get('PYTEST_CURRENT_TEST')})
        raise RuntimeError('Finalization denies network/database/process escape: '+event)
    if event == 'subprocess.Popen':
        executable, argv, cwd, env = args
        if executable != sys.executable or not isinstance(argv,(list,tuple)) or len(argv)!=4 or list(argv[1:3])!=['-B','-c'] or cwd not in (None,str(MAIN)) or env is not None:
            blocked.append({'event':event,'test':os.environ.get('PYTEST_CURRENT_TEST')})
            raise AssertionError('Only exact inherited-guard local Python cold-import tests allowed')
        allowed_python_subprocesses.append(os.environ.get('PYTEST_CURRENT_TEST'))
    if event == 'sqlite3.connect':
        db = os.fsdecode(args[0])
        if db.startswith('file:'):
            uri=urlsplit(db)
            if uri.netloc not in ('','localhost'):raise AssertionError('Nonlocal SQLite forbidden')
            db=unquote(uri.path)
        if db != ':memory:' and not Path(db).resolve().is_relative_to(TEMP):
            raise AssertionError('SQLite test-root guard: '+repr(db)+' root='+str(TEMP))
    paths = []
    if event == 'open' and isinstance(args[0],(str,bytes,os.PathLike)):
        p,mode,flags=args
        writing=(isinstance(mode,str) and any(c in mode for c in 'wax+')) or (isinstance(flags,int) and flags & (os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC|os.O_APPEND))
        if writing:paths=[p]
        elif Path(os.fsdecode(p)).name.startswith('.env') and not Path(os.fsdecode(p)).resolve().is_relative_to(TEMP):
            raise AssertionError('Real secret-file reads forbidden')
    elif event in ('os.mkdir','os.remove','os.rmdir','os.chmod','os.utime'):paths=[args[0]]
    elif event in ('os.rename','os.link','os.symlink'):paths=[args[0],args[1]]
    for p in paths:
        if isinstance(p,(str,bytes,os.PathLike)) and not Path(os.fsdecode(p)).resolve().is_relative_to(TEMP):
            blocked.append({'event':event,'test':os.environ.get('PYTEST_CURRENT_TEST')})
            raise AssertionError('Write outside temporary verification root forbidden')
sys.meta_path.insert(0,MainOnly())
sys.addaudithook(audit)
O1_MAIN_GUARD_INSTALLED=True
